enum Shape {
    Dot,
    Circle(i32),
    Rect { w: i32, h: i32 },
    Label(String),
}

fn size(s: Shape) -> i32 {
    match s {
        Shape::Dot => 0,
        Shape::Circle(r) => 3 * r * r,
        Shape::Rect { w, h } => w * h,
        Shape::Label(t) => t.len() as i32,
    }
}

fn main() {
    println!("{}", size(Shape::Dot));
    println!("{}", size(Shape::Circle(2)));
    println!("{}", size(Shape::Rect { w: 3, h: 4 }));
    println!("{}", size(Shape::Label(String::from("hey"))));
}

enum Shape {
    Dot,
    Circle(i32),
    Rect { w: i32, h: i32 },
    Label(String),
}

fn size(s: &Shape) -> i32 {
    match s {
        Shape::Circle(r) => *r,
        Shape::Rect { w, .. } => *w,
        Shape::Label(t) => t.len() as i32,
        _ => -1,
    }
}

fn main() {
    let a = Shape::Label(String::from("abc"));
    println!("{} {}", size(&a), size(&a));
    let b = Shape::Rect { w: 5, h: 1 };
    println!("{}", size(&b));
    let c = a;
    if size(&c) > 0 {
        println!("moved after");
    }
}

