#[derive(Debug)]
enum E {
    Neg(i32),
    Big,
}
fn check(n: i32) -> Result<i32, E> {
    if n < 0 { return Err(E::Neg(n)); }
    if n > 100 { return Err(E::Big); }
    Ok(n)
}
fn sum(a: i32, b: i32) -> Result<i32, E> {
    let x = check(a)?;
    let y = check(b)?;
    Ok(x + y)
}
fn main() -> Result<(), E> {
    println!("{:?}", sum(1, 2));
    println!("{:?}", sum(-1, 2));
    let t = sum(5, -7)?;
    println!("{}", t);
    Ok(())
}

